// ─────────────────────────────────────────────────────────────────────────────
// TRIAGE RUBRIC — how the sandbox decides: raise-with-legal / defined-process /
// handle-simply. The engine scores SIGNALS present in the query + profile; the
// highest-tier signal wins, ties break toward the more cautious verdict. Each
// signal lists `patterns` (same matching model as topics) and/or `whenObligation`
// / `whenTopic` conditions so structural facts (not just words) can raise a flag.
// This is a TRIAGE AID, not legal advice — the copy makes that explicit.
// ─────────────────────────────────────────────────────────────────────────────

/** @type {{ code:'escalate-legal'|'defined-process'|'handle-simply', label:string, order:number, colour:string, meaning:string }[]} */
export const TRIAGE_VERDICTS = [
  { code: 'escalate-legal', label: 'Raise with the legal / privacy team', order: 3, colour: 'High',
    meaning: 'The situation carries material legal risk, a hard deadline, cross-border complexity, or potential for harm/enforcement. A qualified person should own it. The sandbox gives you the framing and first steps, not the decision.' },
  { code: 'defined-process', label: 'Follow the defined internal process', order: 2, colour: 'Medium',
    meaning: 'This is a known, repeatable scenario with an established procedure (e.g. answering an access request, onboarding a vendor). Follow the runbook; loop in legal only if it deviates.' },
  { code: 'handle-simply', label: 'Handle simply / routine', order: 1, colour: 'Low',
    meaning: 'Low-risk, routine housekeeping that a trained team member can action directly using the checklist, with no escalation needed unless something unusual surfaces.' },
];

/**
 * @typedef {Object} TriageSignal
 * @property {string} id
 * @property {'escalate-legal'|'defined-process'|'handle-simply'} verdict
 * @property {number} weight        Higher = stronger pull toward this verdict.
 * @property {string} reason        Shown to the user as the "why".
 * @property {string[]} [patterns]  Query phrases that fire this signal.
 * @property {string[]} [whenObligation]  Fires if any listed obligation id is in scope.
 * @property {string[]} [whenTopic] Fires if any listed topic id matched.
 * @property {Array<object>} [whenProfile]  Structural profile conditions, e.g. {type:'flag',name:'transfersDataInternationally'}.
 */

