export const DISCLAIMER = 'This Compliance-Query Sandbox is a deterministic, rule-based triage aid built on paraphrased public sources. It is NOT legal advice and NOT an official interpretation of any law or standard. Thresholds, dates and mechanisms change — verify against the cited sources and take qualified advice before acting. Results are organised so you can find the jurisdiction that applies to you; where your location is not specified, all compiled frameworks are shown grouped by jurisdiction.';

export const KB_VERSION = { version: '1.0.0', researchedOn: '2026-07-05', frameworks: FRAMEWORKS.length, obligations: OBLIGATIONS.length, topics: TOPICS.length };

/**
 * Convenience index: obligation id → obligation object. Built eagerly (module is
 * tiny) so the engine can resolve ids without repeated scans. Deterministic.
 * @type {Record<string, Obligation>}
 */
export const OBLIGATION_BY_ID = Object.fromEntries(OBLIGATIONS.map((o) => [o.id, o]));

/** @type {Record<string, Framework>} */
export const FRAMEWORK_BY_ID = Object.fromEntries(FRAMEWORKS.map((f) => [f.id, f]));

/** @type {Record<string, Jurisdiction>} */
export const JURISDICTION_BY_CODE = Object.fromEntries(JURISDICTIONS.map((j) => [j.code, j]));
